def odd_one_out(s):
    from collections import Counter
    counts = Counter(s)
    unpaired_chars = {char for char, count in counts.items() if count % 2 != 0}
    seen = set()
    result = []
    for char in reversed(s):
        if char in unpaired_chars and char not in seen:
            seen.add(char)
            result.append(char)
    return result[::-1]
